from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        if m < n:
            return 0

        suff0 = [0] * n
        suff1 = [0] * n

        def check(x: int) -> bool:
            req_last = (x + points[n - 1] - 1) // points[n - 1]
            suff0[n - 1] = 0
            suff1[n - 1] = max(0, req_last - 1)

            for i in range(n - 2, -1, -1):
                req = (x + points[i] - 1) // points[i]
                extra = max(0, req - 2)

                s0 = suff0[i + 1]
                s1 = suff1[i + 1]
                suff0[i] = max(s0, s1)
                suff1[i] = s0 + extra

            if 2 * n - 1 + 2 * max(suff0[0], suff1[0]) <= m:
                return True

            pref0 = pref1 = 0

            for end in range(1, n):
                i = end - 1
                req = (x + points[i] - 1) // points[i]
                extra = max(0, req - 1)

                pref0, pref1 = max(pref0, pref1), pref0 + extra

                needed_extra = max(pref0 + max(suff0[end], suff1[end]), pref1 + suff0[end])
                base_moves = 2 * n - end - 1

                if base_moves + 2 * needed_extra <= m:
                    return True

            return False

        low, high = 1, max(points) * m
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans
